suspend fun loadDashboard(): Dashboard = coroutineScope {
    val profile = async { api.profile() }
    val orders = async { api.orders() }
    val offers = async { api.offers() }

    // returns only when all three are done; if one throws, the others are cancelled
    Dashboard(profile.await(), orders.await(), offers.await())
}

try {
    show(loadDashboard())
} catch (e: IOException) {
    showError()      // catches the failure of any child
}

suspend fun loadHome(): Home = supervisorScope {
    val feed = async { api.feed() }
    val banners = async { api.banners() }

    Home(
        feed = feed.await(),                                        // required: may throw
        banners = try { banners.await() } catch (e: IOException) { emptyList() } // optional
    )
}

// Does NOT catch the failure: launch returns before the block runs
try {
    scope.launch { riskyCall() }
} catch (e: Exception) { /* never reached for riskyCall's error */ }

// Catches it: the try/catch is inside the coroutine
scope.launch {
    try { riskyCall() } catch (e: IOException) { showError() }
}

// async: the exception is thrown at await
val deferred = scope.async { riskyCall() }
try { deferred.await() } catch (e: IOException) { showError() }

suspend fun loadAll(ids: List<String>): List<Item> = coroutineScope {
    ids.map { id -> async { api.item(id) } }.awaitAll()   // one failure fails everything
}

// Tolerate individual failures
suspend fun loadAvailable(ids: List<String>): List<Item> = supervisorScope {
    ids.map { id -> async { try { api.item(id) } catch (e: IOException) { null } } }
        .awaitAll()
        .filterNotNull()
}

