suspend inline fun <T> suspendRunCatching(block: () -> T): Result<T> =
    try {
        Result.success(block())
    } catch (e: CancellationException) {
        throw e                       // never turn cancellation into a failure value
    } catch (e: Throwable) {
        Result.failure(e)
    }

val result = suspendRunCatching { api.loadUser() }

var uploadJob: Job? = null

fun restartUpload() {
    viewModelScope.launch {
        uploadJob?.cancelAndJoin()          // old upload has fully cleaned up
        uploadJob = launch { uploader.run() } // safe to reuse the resource now
    }
}

sealed interface LoginResult {
    data class Success(val user: User) : LoginResult
    data object WrongPassword : LoginResult
    data class NetworkError(val cause: IOException) : LoginResult
}

suspend fun login(name: String, password: String): LoginResult = try {
    LoginResult.Success(api.login(name, password))
} catch (e: HttpException) {
    if (e.code == 401) LoginResult.WrongPassword else throw e   // unexpected: propagate
} catch (e: IOException) {
    LoginResult.NetworkError(e)
}
